// n8n Code node (JavaScript) — "Run Once for All Items"
// Handles multiple site formats via a fallback chain:
//   1. schema.org JSON-LD (iProperty and PropertyGuru) 
//   2. mudah.my's __NEXT_DATA__ format
//   3. unhandled fallback (logs the URL)

const results = [];

function sanitizeBody(text) {
  return text
    .replace(/<br\s*\/?>/gi, "\n") // Convert <br> to newline
    .replace(/<\/?[^>]+>/g, "")    // Remove any remaining HTML tags
    .replace(/\n{3,}/g, "\n\n")    // Collapse excessive newlines
    .trim();
}

// schema.org JSON-LD (iProperty / PropertyGuru)
function extractSchemaOrg(html) {
  const scriptMatches = [...html.matchAll(/<script type="application\/ld\+json"[^>]*>(.*?)<\/script>/gs)];

  for (const match of scriptMatches) {
    let data;
    try {
      data = JSON.parse(match[1]);
    } catch (e) {
      continue; // not valid JSON, try next script block
    }

    const graph = data['@graph'] || [data];

    // Find the property entity — could be SingleFamilyResidence, Apartment,
    // House, or generic "Residence" depending on property type.
    const property = graph.find(item =>
      item['@type'] && (
        item['@type'].includes('Residence') ||
        item['@type'] === 'House' ||
        item['@type'] === 'Apartment'
      )
    );
    if (!property) continue; // this JSON-LD block isn't the listing schema

    const offer = graph.find(item => item['@type'] === 'Offer');
    const agent = graph.find(item => item['@type'] === 'RealEstateAgent');

    // const faq = graph.find(item => item['@type'] === 'FAQPage');

    const getAdditionalProp = (name) => {
      const found = (property.additionalProperty || []).find(p => p.name === name);
      return found ? found.value : '';
    };

    // Amenities
    const facilitiesToString = (facilityFeature = []) => {
      return facilityFeature
      .filter(item_ => item_.value === true)
      .map(item_ => item_.name)
      .join(", ");
    };

    // console.log(graph);

    return {
      title: property.name,
      property_type: property.accommodationCategory || property['@type'],
      price: offer ? offer.price : '',
      location: property.address ? property.address.streetAddress : '',
      size_sqft: property.floorSize ? property.floorSize.value : '',
      bedrooms: property.numberOfBedrooms || '',
      bathrooms: property.numberOfBathroomsTotal || '',
      furnishing: getAdditionalProp('Furnishing'),
      tenure: getAdditionalProp('Tenure'),
      latitude: property.geo.latitude,
      longitude: property.geo.longitude,
      facilities: facilitiesToString(property.amenityFeature),
      agent_name: agent ? agent.name : '',
      agent_agency: agent && agent.memberOf ? agent.memberOf.name : '',
      // NOTE: schema.org JSON-LD does not include phone numbers on this site —
      // that's masked behind a "View Phone Number" click on iProperty.
      phone: '',
      listing_url: property.url || '',
      // faq
      strategy_used: 'schema_org',
    };
  }
  return null;
}

// mudah.my's __NEXT_DATA__ 
function extractMudah(html) {
  const match = html.match(/<script id="__NEXT_DATA__" type="application\/json">(.*?)<\/script>/s);
  if (!match) return null;

  let nextData;
  try {
    // console.log("DDWAD");
    nextData = JSON.parse(match[1]);
    // console.log(nextData);
  } catch (e) {
    return null;
  }

  const adData = nextData.props?.initialProps?.pageProps?.res?.data?.[0];
  if (!adData || !adData.attributes) return null; // not mudah's structure

  const listing = adData.attributes;
  const params = {};
  (listing.category_params || []).forEach(p => { params[p.id] = p.value; });

  // console.log(params);

  // console.log(listing);

  return {
    title: listing.subject,
    advertisement_id: listing.ad_id || '',
    property_type: params.property_type,
    price: listing.price,
    location: listing.location_label,
    size_sqft: params.size,
    category_id: params.category_id || '', // Probably category IDs for how the website configures their property ID system?
    rooms: params.rooms || '', // Bedrooms
    rental_deposit: params.rendepo || '',
    // bedrooms: params.bedrooms || '',
    bathrooms: params.bathroom || '',
    parking: params.parking || '' ,
    furnishing: params.furnished || '',
    facilities: params.facilities || '',
    add_facilities: params.additional_facilities || '',
    floor_range: params.floor_range || '',
    description: sanitizeBody(listing.body) || '',
    tenure: params.tenure || '',
    landlord_name: listing.name,
    tenant_name: '',
    phone: listing.phone,
    listing_url: adData.links?.self || '',
    strategy_used: 'mudah_next_data',
  };
}

