// n8n Code node (JavaScript) — "Run Once for Each Item"
// Builds a Turso HTTP API INSERT request for the full listings schema,
// with every value bound as a parameter (never string-concatenated into
// the SQL itself — this is what keeps it injection-safe).
// Output feeds directly into an HTTP Request node's Body field.

const record = $input.first().json;

// Helper: wraps a value in Turso's required { type, value } shape.
// Turso's "value" must always be sent as a string (even for numbers),
// with "type" telling it how to interpret that string.
function arg(value, type = "text") {
  if (value === null || value === undefined || value === "") {
    return { type: "null" };
  }
  return { type, value: String(value) };
}

const columns = [
  "advertisement_id", "listing_title", "property_type", "price", "price_per_sqft",
  "size_sqft", "bedrooms", "bathrooms", "furnishing", "tenure", "floor",
  "car_parks", "facilities", "full_address", "area", "latitude", "longitude",
  "website", "listing_url", "listing_date", "scraped_date", "owner_name",
  "agent_name", "agent_agency", "phone", "contact_status", "last_contact",
  "viewing_date", "remarks", "summary", "rating", "rating_reason",
  "scam_score", "scam_reasons", "duplicate_confidence",
  "outreach_message", "client_match", "strategy_used", "created_date", "updated_date",
];

// Numeric columns get typed as "integer" or "float"; everything else defaults to "text"
const numericIntegerCols = ["bedrooms", "bathrooms", "car_parks", "scam_score", "duplicate_confidence"];
const numericFloatCols = ["price", "price_per_sqft", "size_sqft", "latitude", "longitude", "rating"];

const placeholders = columns.map(() => "?").join(", ");
const sql = `INSERT INTO listings (${columns.join(", ")}) VALUES (${placeholders})`;

const args = columns.map((col) => {
  const value = record[col];
  if (numericIntegerCols.includes(col)) return arg(value, "integer");
  if (numericFloatCols.includes(col)) return arg(value, "float");
  return arg(value, "text");
});

const body = {
  requests: [
    { type: "execute", stmt: { sql, args } },
    { type: "close" },
  ],
};

return [{
  json: {
    ...record,
    turso_request_body: JSON.stringify(body),
  }
}];

// n8n Code node (JavaScript) — "Run Once for Each Item"
// Merges three upstream sources into one clean record:
//   1. Scraped + parsed listing data (from your site-router Code node)
//   2. Basic LLM Chain output: { rating, reason, outreach_message }
//   3. AI Agent output: { scam_score, scam_reasons, duplicate_score, duplicate_of_ad_id }
//
// Adjust the node names in $('...') below to match your actual node names in the canvas.

const scraped = $('Code in JavaScript – Extract HTML To JSON').first().json;
// console.log(scraped);

let llmResult = {};
const rawLlm = $input.first().json.output;
//   console.log("DWADA");
//   console.log($input.first());
// console.log($input.first().json);

try {
  const rawLlm = $input.first().json.output;
  // console.log("DWADA");
  // console.log(rawLlm);
  llmResult = rawLlm;
} catch (e) {
  llmResult = { rating: null, reason: '', outreach_message: '' };
}

let agentResult = {};
try {
  const rawAgent = $('AI Agent – Scam & Duplicate Entry Detection').first().json.output || '{}';
  // agentResult = JSON.parse(rawAgent);
  agentResult = rawAgent;
} catch (e) {
  agentResult = { scam_score: null, scam_reasons: [], duplicate_score: null, duplicate_of_ad_id: null };
}

const nowIso = new Date().toISOString();

const merged = {
  // Identity / dedup key
  listing_id: scraped.advertisement_id || '',

  // Listing basics
  listing_title: scraped.title || '',
  property_type: scraped.property_type || '',
  price: parseFloat(String(scraped.price || '').replace(/[^\d.]/g, '')) || null,
  price_per_sqft: scraped.price_per_sqft ?? null,
  size_sqft: parseFloat(String(scraped.size_sqft || '').replace(/[^\d.]/g, '')) || null,
  bedrooms: llmResult.bedrooms ?? scraped.bedrooms ?? null, // prefer LLM-normalized value if present
  bathrooms: llmResult.bathrooms ?? scraped.bathrooms ?? null,
  furnishing: scraped.furnishing || '',
  tenure: scraped.tenure || '',
  floor: scraped.floor || '',
  car_parks: scraped.car_parks ?? null,
  facilities: Array.isArray(scraped.facilities) ? JSON.stringify(scraped.facilities) : (scraped.facilities || ''),

  // Location
  full_address: scraped.location || scraped.full_address || '',
  area: scraped.area || '',
  latitude: scraped.latitude ?? null,
  longitude: scraped.longitude ?? null,

  // Source & tracking
  website: scraped.source_website || '',
  listing_url: scraped.listing_url || '',
  listing_date: scraped.date_listed || '',
  scraped_date: scraped.date_scraped || nowIso,

  // Contacts
  owner_name: scraped.owner_name || '',
  agent_name: scraped.agent_name || '',
  agent_agency: scraped.agent_agency || '',
  phone: scraped.phone || '',

  // Outreach / pipeline — new rows always start here
  contact_status: 'Not Contacted',
  last_contact: '',
  viewing_date: '',
  remarks: '',

  // AI-generated fields
  summary: llmResult.summary || '',
  rating: llmResult.rating ?? null,
  rating_reason: llmResult.reason || '',
  scam_score: agentResult.scam_score ?? null,
  scam_reasons: Array.isArray(agentResult.scam_reasons) ? agentResult.scam_reasons.join('; ') : '',
  duplicate_confidence: agentResult.duplicate_score ?? null,
  duplicate_of_ad_id: agentResult.duplicate_of_ad_id || '',
  outreach_message: llmResult.outreach_message || '',
  client_match: '',
  strategy_used: scraped.strategy_used || '',

  // Timestamps
  created_date: nowIso,
  updated_date: nowIso,
};

return [{ json: merged }];
